<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no">
<title>Balloon Archer — Level 1</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  :root{ --ink:#231c2b; --cream:#fff3dd; --gold:#ffc857; --red:#ff5d6c; }
  *{box-sizing:border-box}
  html,body{margin:0;height:100%;background:#0d1018;overflow:hidden;font-family:'Fredoka',sans-serif}
  body{display:flex;align-items:center;justify-content:center}
  #stage{position:relative;width:min(100vw,calc(100vh * 16 / 9));height:min(100vh,calc(100vw * 9 / 16));box-shadow:0 0 0 1px #3b3b52,0 24px 80px #000a;overflow:hidden;background:#2b3a67}
  canvas{display:block;width:100%;height:100%;cursor:none;touch-action:none}
  #overlay{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(17,17,32,.55);backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}
  #overlay.show{display:flex}
  .panel{position:relative;width:min(78%,640px);padding:34px 42px 38px;text-align:center;background:linear-gradient(180deg,#fff8e9,#ffe5c4);border:5px solid var(--ink);border-radius:22px;box-shadow:0 12px 0 #1a1422,0 28px 60px #0008;animation:pop .38s cubic-bezier(.2,1.7,.4,1) both}
  @keyframes pop{from{transform:scale(.86) translateY(14px);opacity:0}to{transform:scale(1) translateY(0);opacity:1}}
  .kicker{font-family:'Press Start 2P',monospace;font-size:11px;letter-spacing:1px;color:#a15a4a;margin-bottom:12px}
  h1{margin:0;line-height:.95;font-size:clamp(32px,5.2vw,66px);font-weight:700;color:var(--ink);letter-spacing:-1px;text-shadow:3px 4px 0 #ffc857}
  h2{margin:0 0 8px;font-size:clamp(28px,4vw,48px);font-weight:700;color:var(--ink)}
  .sub{margin:14px auto 0;max-width:470px;font-size:clamp(13px,1.5vw,17px);color:#6b5260;line-height:1.45}
  .hint{margin:18px auto 0;font-family:'Press Start 2P',monospace;font-size:10px;line-height:1.9;color:#8a6b74}
  .btn{margin-top:22px;padding:14px 36px;font-family:'Fredoka',sans-serif;font-weight:700;font-size:clamp(15px,1.8vw,20px);color:#2a1b20;background:linear-gradient(180deg,#ffd76a,#ffb23f);border:4px solid var(--ink);border-radius:14px;box-shadow:0 6px 0 #1a1422;cursor:pointer;transition:transform .08s,box-shadow .08s,filter .15s}
  .btn:hover{filter:brightness(1.07);transform:translateY(-2px);box-shadow:0 8px 0 #1a1422}
  .btn:active{transform:translateY(5px);box-shadow:0 1px 0 #1a1422}
  .best{margin-top:16px;font-family:'Press Start 2P',monospace;font-size:10px;color:#a15a4a}
  .bigscore{font-family:'Press Start 2P',monospace;font-size:clamp(30px,5vw,58px);color:#d6544f;text-shadow:3px 3px 0 #2b1d24;margin:16px 0 6px}
  .medal{font-size:34px;line-height:1}
  #mute{position:absolute;right:14px;bottom:12px;z-index:3;padding:6px 12px;font-family:'Press Start 2P',monospace;font-size:9px;color:#ffe6bd;background:#20182bb8;border:2px solid #ffe6bd66;border-radius:9px;cursor:pointer}
  #mute:hover{background:#20182b}
</style>
</head>
<body>
<div id="stage">
  <canvas id="game" width="1280" height="720"></canvas>
  <button id="mute" title="Mute (M)">SOUND ON</button>
  <div id="overlay" class="show"><div class="panel" id="panel"></div></div>
</div>
<script>
'use strict';
const cvs=document.getElementById('game'),ctx=cvs.getContext('2d');
const W=1280,H=720,GY=628;
const overlay=document.getElementById('overlay'),panel=document.getElementById('panel'),muteBtn=document.getElementById('mute');
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>v<a?a:v>b?b:v;
function rr(x,y,w,h,r){r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}

